138	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
139	        var held = watches.findByPersonIdAndUser(person.getId(), user);
140	        if (on == held.isPresent()) {
141	            return person;
