149	            }
150	        } else {
151	            watches.delete(held.get());
152	        }
153	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
154	                + " name=" + person.getName());
