159	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
160	        requireSheet(sheetId);
161	        requireFreeName(sheetId, name.trim(), null);
162	        String key = contactKey(contact);
163	        requireFreeContact(sheetId, key, null);
164	        Rollup.Snapshot before = rollup.take(sheetId);
165	        Person person = new Person(sheetId, name.trim(), grade);
166	        person.setTerms(terms);
167	        person.setContact(key);
168	        person = saved(person);
169	        audit("PERSON_ADDED", person, user, today(sheetId), (terms == null ? "" : " terms=" + terms)
170	                + (key == null ? "" : " contact=" + key));
171	        rollup.recordChanges(sheetId, user, before);
172	        return person;
