175	    @Transactional
176	    /** Change a person's name, and record the grade from a date (the sheet's today when none is given),
177	     *  keeping the grades already recorded; a save leaving the grade as it is on the sheet's today, with no
178	     *  from-date, records nothing. Their own terms are set to those given (none clears them), and their
179	     *  contact to the one given (blank clears it). */
180	    public Person update(String sheetId, String user, long personId, long version, String name, String grade,
181	            LocalDate gradeFrom, Integer terms, String contact) {
182	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
183	        if (person.getVersion() != version) {
184	            throw new PersonVersionConflictException(person);
185	        }
186	        requireFreeName(sheetId, name.trim(), person.getId());
187	        String key = contactKey(contact);
188	        requireFreeContact(sheetId, key, person.getId());
189	        Rollup.Snapshot before = rollup.take(sheetId);
190	        LocalDate today = today(sheetId);
191	        person.setName(name.trim());
192	        boolean termsChanged = !Objects.equals(terms, person.getTerms());
193	        person.setTerms(terms);
194	        boolean contactChanged = !Objects.equals(key, person.getContact());
195	        person.setContact(key);
196	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
197	            person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
198	        }
199	        Person updated = saved(person);
200	        audit("PERSON_EDITED", updated, user, today, (termsChanged ? " terms=" + (terms == null ? "" : terms) : "")
201	                + (contactChanged ? " contact=" + (key == null ? "" : key) : ""));
202	        rollup.recordChanges(sheetId, user, before);
203	        return updated;
204	    }
