206	    /** Give each of the chosen people the grade from a date, in list order, exactly as the person form
207	     *  would with their name and terms left as they are; the people changed, in list order. A viewer's goes
208	     *  through with no one changed. */
209	    @Transactional
210	    public List<Person> bulkGrade(String sheetId, String user, List<Long> personIds, String grade, LocalDate from) {
211	        requireSheet(sheetId);
212	        if (roles.isViewer(sheetId, user)) {
213	            return List.of();
214	        }
215	        Set<Long> chosen = Set.copyOf(personIds);
216	        List<Person> picked = people.findBySheetIdOrderByIdAsc(sheetId).stream()
217	                .filter(p -> chosen.contains(p.getId())).toList();
218	        if (picked.size() != chosen.size()) {
219	            throw new PersonNotFoundException();
220	        }
221	        return picked.stream().map(p -> update(sheetId, user, p.getId(), p.getVersion(), p.getName(), grade, from,
222	                p.getTerms(), p.getContact())).toList();
223	    }
