253	    /** A steward merges a person into another: the merged person's claims move to the other (numbers and
254	     *  dates kept, listed after the other's in the order they were added, each losing any figure a statement
255	     *  bound); their name and aliases become the other's aliases; their patrons are added to the other's (not
256	     *  themselves, no repeats), anyone naming them as patron names the other instead (no repeats), and their
257	     *  pool memberships move to the other (shares added, at most 100.00, where the other is already a member)
258	     *  as do their figures for closed periods. Their statements, holds, watchers and contact are dropped, and
259	     *  they leave the sheet. Refused for anyone but a steward, for the same person, and when either is
260	     *  retired. */
261	    @Transactional
262	    public Person merge(String sheetId, String user, long personId, long intoId) {
263	        Person from = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
264	        Person into = people.findByIdAndSheetId(intoId, sheetId).orElseThrow(PersonNotFoundException::new);
265	        if (!roles.isSteward(sheetId, user)) {
266	            throw new MergeRefusedException("Only a steward may merge people.");
267	        }
268	        if (from.getId().equals(into.getId())) {
269	            throw new MergeRefusedException("A person cannot be merged into themselves.");
270	        }
271	        if (from.isRetired() || into.isRetired()) {
272	            throw new MergeRefusedException("A retired person cannot be merged.");
273	        }
274	        Rollup.Snapshot before = rollup.take(sheetId);
275	        List<Claim> moving = new ArrayList<>(
276	                claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, from.getId()));
277	        moving.sort(Comparator.comparing(Claim::getId));
278	        long order = claims.maxListOrder(sheetId);
279	        for (Claim claim : moving) {
280	            claim.setPersonId(into.getId());
281	            claim.setStated(false, null);
282	            claim.setListOrder(++order);
283	        }
284	        claims.saveAll(moving);
285	
286	        List<Long> intoPatrons = new ArrayList<>(patronsOf(into.getId()));
287	        for (Patron patron : patrons.findByPersonIdOrderByIdAsc(from.getId())) {
288	            if (!patron.getPatronId().equals(into.getId()) && !intoPatrons.contains(patron.getPatronId())) {
289	                patrons.save(new Patron(sheetId, into.getId(), patron.getPatronId()));
290	                intoPatrons.add(patron.getPatronId());
291	            }
292	            patrons.delete(patron);
293	        }
294	        for (Patron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
295	            if (!patron.getPatronId().equals(from.getId())) {
296	                continue;
297	            }
298	            if (!patron.getPersonId().equals(into.getId())
299	                    && !patrons.existsByPersonIdAndPatronId(patron.getPersonId(), into.getId())) {
300	                patrons.save(new Patron(sheetId, patron.getPersonId(), into.getId()));
301	            }
302	            patrons.delete(patron);
303	        }
304	
305	        for (Pool pool : pools.findBySheetIdOrderByIdAsc(sheetId)) {
306	            if (pool.hasMember(from.getId())) {
307	                pool.moveMember(from.getId(), into.getId());
308	            }
309	        }
310	        for (Period period : periods.findBySheetIdOrderByFromDateAsc(sheetId)) {
311	            period.moveClosedTotal(from.getId(), into.getId());
312	        }
313	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
314	        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(from.getId()));
315	        // everything naming them goes before they do
316	        people.flush();
317	
318	        List<String> names = new ArrayList<>();
319	        names.add(from.getName());
320	        names.addAll(from.getAliases());
321	        people.delete(from);
322	        people.flush();
323	        names.forEach(into::addAlias);
324	        Person merged = people.saveAndFlush(into);
325	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + from.getName()
326	                + " into=" + merged.getName());
327	        rollup.recordChanges(sheetId, user, before);
328	        return merged;
329	    }
